mapper.update:
UPDATE contract_fee
institution_no = #{institutionNo}, fee_amount = #{feeAmount}, fee_date = #{feeDate}, payment_method = #{paymentMethod}, recorded_by = #{recordedBy}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT COALESCE(SUM(cf.fee_amount), 0) FROM contract_fee cf
INNER JOIN institution i ON cf.institution_no = i.institution_no
WHERE YEAR(cf.create_time) = #{year} AND i.region = #{region}
